create extension if not exists "pgcrypto";
create type source_content_kind as enum ('course_material','teacher_or_lesson_note','user_annotation','user_answer','correction','uncertain');
create type review_status as enum ('candidate','approved','rejected','inactive');
create table source_documents(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),title text not null,storage_path text,lesson_date date,status review_status not null default 'candidate',created_at timestamptz not null default now());
create table lessons(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),title text not null,lesson_date date,created_at timestamptz not null default now());
create table source_pages(id uuid primary key default gen_random_uuid(),document_id uuid not null references source_documents(id),page_number int not null,extracted_text text,created_at timestamptz not null default now(),unique(document_id,page_number));
create table concepts(id uuid primary key default gen_random_uuid(),canonical_key text not null unique,title text not null,description text,category text not null,difficulty int not null check(difficulty between 1 and 5),status review_status not null default 'candidate',created_at timestamptz not null default now());
create table concept_sources(concept_id uuid references concepts(id),source_page_id uuid references source_pages(id),lesson_id uuid references lessons(id),kind source_content_kind not null,confidence numeric(4,3),excerpt text,primary key(concept_id,source_page_id,kind));
create table concept_examples(id uuid primary key default gen_random_uuid(),concept_id uuid not null references concepts(id),text text not null,translation text,kind source_content_kind not null,approved boolean not null default false);
create table candidate_concepts(id uuid primary key default gen_random_uuid(),document_id uuid references source_documents(id),payload jsonb not null,status review_status not null default 'candidate',matched_concept_id uuid references concepts(id),created_at timestamptz not null default now());
create table questions(id uuid primary key default gen_random_uuid(),primary_concept_id uuid not null references concepts(id),type text not null,prompt text not null,choices jsonb,accepted_answers jsonb not null,explanation text,difficulty int not null,active boolean not null default true,created_at timestamptz not null default now());
create table question_concepts(question_id uuid references questions(id),concept_id uuid references concepts(id),is_primary boolean not null default false,primary key(question_id,concept_id));
create table quiz_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),mode text not null,started_at timestamptz not null default now(),completed_at timestamptz,xp int not null default 0);
create table question_attempts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),session_id uuid references quiz_sessions(id),question_id uuid references questions(id),primary_concept_id uuid references concepts(id),user_answer text,accepted_answer text,correct boolean not null,response_ms int,difficulty int,attempt_number int,source_lesson_id uuid references lessons(id),question_type text,created_at timestamptz not null default now());
create table concept_mastery(user_id uuid references auth.users(id),concept_id uuid references concepts(id),mastery numeric(5,2) not null default 0,attempts int not null default 0,correct_attempts int not null default 0,recent_performance jsonb not null default '[]',last_practiced timestamptz,next_review timestamptz,primary key(user_id,concept_id));
create table user_stats(user_id uuid primary key references auth.users(id),xp int not null default 0,current_streak int not null default 0,longest_streak int not null default 0,last_practice_date date);
create table ingestion_jobs(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),document_id uuid references source_documents(id),status text not null,provider text,error text,created_at timestamptz not null default now());
alter table source_documents enable row level security; alter table lessons enable row level security; alter table quiz_sessions enable row level security; alter table question_attempts enable row level security; alter table concept_mastery enable row level security; alter table user_stats enable row level security;
create policy "own documents" on source_documents for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own lessons" on lessons for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own sessions" on quiz_sessions for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own attempts" on question_attempts for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own mastery" on concept_mastery for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own stats" on user_stats for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
